INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Wartung > Prävention
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist präventive Wartung immer notwendig, um IT-Systemausfälle zu vermeiden?', 2, '[{"text": "Nein", "correct": true, "because": "Reaktive Maßnahmen sind möglich, aber Prävention ist effektiver"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend, aber empfohlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann präventive Wartung die Lebensdauer von Hardware verlängern?', 2, '[{"text": "Ja", "correct": true, "because": "Regelmäßige Pflege reduziert Verschleiß"}, {"text": "Nein", "correct": false, "because": "Prävention wirkt positiv auf Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen präventive Maßnahmen immer während des Betriebs durchgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Geplante Stillstände sind oft effizienter"}, {"text": "Ja", "correct": false, "because": "Prävention kann außerhalb des Betriebs erfolgen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Software-Updates als Teil der präventiven Wartung betrachtet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Updates verhindern Sicherheitslücken und Fehler"}, {"text": "Nein", "correct": false, "because": "Softwarepflege ist präventiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist präventive Wartung ausschließlich auf physische Komponenten beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Sie umfasst auch Software und Systeme"}, {"text": "Ja", "correct": false, "because": "Prävention ist umfassend"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die präventive Wartung primär?', 3, '[{"text": "Vermeidung von Systemausfällen", "correct": true, "because": "Prävention minimiert Risiken"}, {"text": "Erhöhung der Betriebskosten", "correct": false, "because": "Gegenteil ist Ziel"}, {"text": "Verkürzung der Systemlebensdauer", "correct": false, "because": "Nicht gewünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme ist ein typisches Beispiel für präventive Wartung?', 2, '[{"text": "Regelmäßige Backups", "correct": true, "because": "Schützt vor Datenverlust"}, {"text": "Notfallreparatur", "correct": false, "because": "Reaktiv, nicht präventiv"}, {"text": "Neuinstallation", "correct": false, "because": "Kein präventiver Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird oft für präventive Wartung zur Überwachung eingesetzt?', 2, '[{"text": "Monitoring-Software", "correct": true, "because": "Erkennt Probleme frühzeitig"}, {"text": "Texteditor", "correct": false, "because": "Kein Wartungstool"}, {"text": "Grafikprogramm", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann durch fehlende präventive Wartung entstehen?', 3, '[{"text": "Unerwartete Systemausfälle", "correct": true, "because": "Ohne Prävention steigt das Risiko"}, {"text": "Schnellere Systemleistung", "correct": false, "because": "Unrealistisch"}, {"text": "Automatische Fehlerkorrektur", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Ansatz beschreibt präventive Wartung am besten?', 2, '[{"text": "Probleme verhindern, bevor sie auftreten", "correct": true, "because": "Kern der Prävention"}, {"text": "Reparaturen nach Ausfällen", "correct": false, "because": "Reaktiv, nicht präventiv"}, {"text": "Systeme abschalten", "correct": false, "because": "Kein Wartungsansatz"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gehören zur präventiven Wartung?', 4, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Schützt vor Schwachstellen"}, {"text": "Hardware-Reinigung", "correct": true, "because": "Verhindert Überhitzung"}, {"text": "Monitoring", "correct": true, "because": "Früherkennung von Problemen"}, {"text": "Notfallreparaturen", "correct": false, "because": "Reaktiv, nicht präventiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet präventive Wartung?', 3, '[{"text": "Geringere Ausfallzeiten", "correct": true, "because": "Probleme werden vermieden"}, {"text": "Höhere Systemzuverlässigkeit", "correct": true, "because": "Stabilität wird erhöht"}, {"text": "Kostensenkung langfristig", "correct": true, "because": "Reparaturen reduziert"}, {"text": "Schnellere Hardwareverschleiß", "correct": false, "because": "Gegenteil tritt ein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme kann präventive Wartung verhindern?', 4, '[{"text": "Datenverlust", "correct": true, "because": "Durch Backups"}, {"text": "Sicherheitslücken", "correct": true, "because": "Durch Updates"}, {"text": "Hardwareausfälle", "correct": true, "because": "Durch Pflege"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Kein Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten können durch präventive Wartung geschützt werden?', 3, '[{"text": "Server", "correct": true, "because": "Hardwarewartung"}, {"text": "Betriebssysteme", "correct": true, "because": "Software-Updates"}, {"text": "Netzwerke", "correct": true, "because": "Monitoring und Pflege"}, {"text": "Büromöbel", "correct": false, "because": "Nicht IT-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze unterstützen präventive Wartung?', 3, '[{"text": "Regelmäßige Inspektionen", "correct": true, "because": "Erkennen Schwachstellen"}, {"text": "Automatische Updates", "correct": true, "because": "Schützen Software"}, {"text": "Geplante Stillstände", "correct": true, "because": "Ermöglichen Wartung"}, {"text": "Spontane Reparaturen", "correct": false, "because": "Reaktiv, nicht präventiv"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Präventive Wartung reduziert ungeplante Ausfälle. b) Sie ist immer teurer als reaktive Wartung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ausfälle ja, Kosten langfristig geringer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Backups sind eine Form der präventiven Wartung. b) Präventive Wartung erfordert keinen Zeitplan.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Backups ja, Planung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Monitoring ist ein Werkzeug der präventiven Wartung. b) Präventive Wartung betrifft nur Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Monitoring ja, auch Hardware"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Präventive Wartung kann Sicherheitsrisiken minimieren. b) Sie ist nur bei alten Systemen sinnvoll.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit ja, alle Systeme profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Regelmäßige Updates sind präventive Wartung. b) Präventive Wartung garantiert keine Ausfälle.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Updates ja, Garantie unmöglich"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');

